import type { IReranker, RerankItem, RerankScore } from './reranker.js';

//** GENERATED BY CLAUDE AI - LOCAL DEV TETING - TODO REPLACE WITH PROVIDER */

// local stand-in for the configured cross-encoder (models.json role "reranker" →
// cross-encoder/ms-marco-MiniLM-L-6-v2). Scores by weighted term overlap with IDF
// approximation and proximity bonus so rank=true works offline with no model download.
// A real cross-encoder swaps in behind IReranker without touching recall.
export class LocalReranker implements IReranker {
  async rank(query: string, items: RerankItem[]): Promise<RerankScore[]> {
    const queryTerms = tokenize(query);
    if (queryTerms.size === 0) return items.map((item) => ({ id: item.id, score: 0 }));

    const scored = items.map((item, index) => {
      const docTokens = tokenize(item.text);
      const docSequence = tokenizeSequence(item.text);
      const querySequence = tokenizeSequence(query);
      return {
        score: {
          id: item.id,
          score: combinedScore(queryTerms, querySequence, docTokens, docSequence),
        } as RerankScore,
        index,
      };
    });

    // descending relevance; ties keep the incoming (cosine) order so reranking never churns equal hits
    return scored
      .sort((a, b) => b.score.score - a.score.score || a.index - b.index)
      .map((s) => s.score);
  }
}

// --- scoring ---

// weighted overlap normalized by total query weight, plus a proximity bonus
function combinedScore(
  queryTerms: Set<string>,
  querySeq: string[],
  docTokens: Set<string>,
  docSeq: string[],
): number {
  const overlap = weightedOverlapScore(queryTerms, docTokens);
  const proximity = proximityBonus(querySeq, docSeq);
  // proximity contributes up to ~15% on top of the base overlap score
  return overlap + proximity * 0.15;
}

// normalized by total query weight so a longer document does not win on raw hit count alone;
// rare (longer) terms are upweighted as a cheap IDF proxy
function weightedOverlapScore(query: Set<string>, doc: Set<string>): number {
  let hits = 0;
  let total = 0;
  for (const term of query) {
    if (STOPWORDS.has(term)) continue;
    const w = termWeight(term);
    total += w;
    if (doc.has(term)) hits += w;
  }
  return total === 0 ? 0 : hits / total;
}

// small bonus [0, 1] when consecutive query terms appear adjacently in the doc;
// signals phrase-level relevance that bag-of-words misses
function proximityBonus(querySeq: string[], docSeq: string[]): number {
  if (querySeq.length < 2) return 0;

  const docBigrams = buildBigrams(docSeq);
  const queryBigrams = buildBigrams(querySeq.filter((t) => !STOPWORDS.has(t)));
  if (queryBigrams.size === 0) return 0;

  let matched = 0;
  for (const bigram of queryBigrams) if (docBigrams.has(bigram)) matched++;
  return matched / queryBigrams.size;
}

// crude IDF proxy: log(length + 1) so longer/rarer tokens carry more weight than "a", "i"
function termWeight(term: string): number {
  return Math.log(term.length + 1);
}

// --- tokenization ---

function tokenize(text: string): Set<string> {
  return new Set(tokenizeSequence(text));
}

// preserves order for proximity checks
function tokenizeSequence(text: string): string[] {
  return (text.toLowerCase().match(/[a-z0-9]+/g) ?? []).filter((t) => !STOPWORDS.has(t));
}

function buildBigrams(tokens: string[]): Set<string> {
  const bigrams = new Set<string>();
  for (let i = 0; i < tokens.length - 1; i++) bigrams.add(`${tokens[i]}|${tokens[i + 1]}`);
  return bigrams;
}

// --- stopwords ---

// common English function words — high frequency, low discriminative value
const STOPWORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'been', 'being',
  'but', 'by', 'do', 'does', 'for', 'from', 'had', 'has', 'have',
  'he', 'her', 'him', 'his', 'how', 'i', 'if', 'in', 'is', 'it',
  'its', 'me', 'my', 'no', 'not', 'of', 'on', 'or', 'our', 'she',
  'so', 'some', 'than', 'that', 'the', 'their', 'them', 'then',
  'there', 'they', 'this', 'to', 'us', 'was', 'we', 'were', 'what',
  'when', 'where', 'which', 'who', 'will', 'with', 'would', 'you',
]);